    boolean showStatus=resumed&&now-lastPowerQuery>=30000;
    if((((recording&&powerForSession)||confirmRelease)&&now-lastPowerQuery>=10000||showStatus)&&!powerQuery){lastPowerQuery=now;powerQuery=true;controls.execute(()->{if(confirmRelease)power.release();else power.refresh();main.post(()->{powerQuery=false;updateUi();});});}
