  private void closeCamera(String reason){if(destroyed)return;adaptive.stop();adaptiveRequested=false;launch.stop();gate.cancel();recordEpoch++;opening=false;frames=0;health.reset();boolean hadRecord=recording||recordStarting||recordStopping;recording=recordStarting=false;recordStopping=hadRecord;setStatus(reason);if(closing)return;closing=true;updateUi();capture.post(()->{try{stopInternal();}finally{releasePower();main.post(()->{closing=false;recordStopping=false;updateUi();writeState();if(!destroyed)maybeAutoStart();});}});}
  private void updateUi(){if(startButton==null)return;startButton.setEnabled(!closing&&!recording&&!recordStarting&&!recordStopping&&(!opening||frames>=3));stopButton.setEnabled((recording||recordStarting||(opening&&launch.isPending()))&&!recordStopping);archiveButton.setEnabled(!recording&&!recordStarting&&!recordStopping&&!closing);for(Button b:new Button[]{startButton,stopButton,archiveButton})b.setAlpha(b.isEnabled()?1f:.45f);status.setText(VideoPublisher.busy()&&!recording?message+" · сборка видео":message);status.setTextColor(recording?0xFFFF706B:Color.WHITE);adaptiveText.setText(adaptive.status());adaptiveText.setVisibility(adaptive.halted()?View.VISIBLE:View.GONE);followButton.setVisibility(adaptive.halted()&&opening&&!closing?View.VISIBLE:View.GONE);long s=recording?Math.max(0,(SystemClock.elapsedRealtime()-recordStartedAt)/1000):0;timer.setText(recordStarting?"Подготовка":recordStopping?"Сохранение":String.format(Locale.ROOT,"%02d:%02d:%02d",s/3600,s/60%60,s%60));powerText.setText(power.statusText());}
  private void setStatus(String value){message=value;updateUi();writeState();}
  private void writeState(){try{JSONObject s=new JSONObject();s.put("message",message);s.put("cameraId",cameraId);s.put("selectedId",selectedId);s.put("fullFrame",!paddingCorrected);s.put("paddingCorrectionRequested",preferences.getBoolean("legacy_padding_correction",false));s.put("paddingCorrectionApplied",paddingCorrected);s.put("detail",detail);s.put("frames",frames);s.put("opening",opening);s.put("recording",recording);s.put("recordStarting",recordStarting);s.put("recordStopping",recordStopping);s.put("settingsVisible",settingsVisible);s.put("autoRecordOnOpen",preferences.getBoolean("auto_record",true));s.put("autoRecordPending",launch.isPending());s.put("powerHoldEnabled",preferences.getBoolean("power_hold",false));s.put("powerHoldStatus",power.statusText());s.put("adaptiveEnabled",preferences.getBoolean("adaptive_views",true));s.put("eventsOnly",preferences.getBoolean("events_only",false));s.put("adaptiveStatus",adaptive.status());s.put("lastVideo",lastVideo==null?JSONObject.NULL:lastVideo.toString());s.put("updatedMs",System.currentTimeMillis());File dir=getExternalFilesDir(null);if(dir!=null)try(FileOutputStream out=new FileOutputStream(new File(dir,"state.json"))){out.write(s.toString(2).getBytes(StandardCharsets.UTF_8));}}catch(Exception ignored){}}
  private void refreshMemory(){if(memoryQuery||destroyed)return;memoryQuery=true;lastMemoryQuery=SystemClock.elapsedRealtime();files.execute(()->{String text;try{RecordingStore.Snapshot s=new RecordingStore(this).snapshot();text=String.format(Locale.ROOT,"Память: занято %d%% · свободно %.1f ГБ · видео %.1f ГБ (%d)",s.usedPercent,s.availableBytes/1073741824.0,s.recordingBytes/1073741824.0,s.clips);}catch(Exception e){text="Память: каталог записи недоступен";}String value=text;main.post(()->{memoryQuery=false;if(!destroyed)memoryText.setText(value);});});}
